"""Writes production/script.md and production/storyboard.md from script.json + timeline.json."""
import json, pathlib
ROOT = pathlib.Path(__file__).resolve().parents[2]
tl = json.load(open(ROOT / "src/data/timeline.json"))
def mmss(x): return f"{int(x//60)}:{x%60:05.2f}"
SCENES = {
 "hook": ("A · Hook", "Three.js night globe (land dots from the site's own world map). One application arcs from Bengaluru to Berlin and stops at a closed door; an illustrative listing card explains why.", "Slow push-in from over the Indian Ocean, pulling back to the full corridor.", "Fade up from black", "Low D drone, air, distant FM bells", "Arc launch whoosh, travelling data blips, soft low impact at the door, ember crackle"),
 "problem": ("B · Problem", "CSS 3D wall of 192 abstract listing cards. Search types, a card is clicked and applied, more fly off; the wall dims by permit / sponsorship while match badges still glow; applications stream out, replies stay empty, 'Your name' burns away.", "Tilted plane drifting, then a long pull-back to show the wall's scale, then a push into darkness.", "Dissolve into typography", "Half-time pulse, Dm9-Bb-Gm-A pads, filtered arpeggio; bed drops out after the last line", "Typing ticks, clicks, stamp thuds, badge pops, outgoing whooshes, crackle, strike swipe, soft impact"),
 "reveal": ("C · Logo reveal", "Horizon line of light; the three official mark polygons fly in from 3D, outline-draw, fill, catch a light sweep; the wordmark wipes in; dust converges. Logo rises; three promises reveal in columns.", "Subtle push on the logo; logo lifts and scales as the promises appear.", "Hard cut from silence", "Restraint, riser, impact, lift into F-C-Dm-Bb", "Riser, three mechanical 'shard lands' thunks, low impact, airy whoosh, ticks per promise"),
 "product": ("D · Product", "Real screens from the running app (demo mode, fictional sample data): resume → profile extraction, validation gates (curated taxonomy, Stack Overflow tags, ESCO, email DNS), dashboard spotlights, job detail with seven factor rows, tailoring with a real Accept click (before/after captures), specialist review checklist + submission receipt, tracker and phones.", "Floating 3D screens with perspective settles, sheen passes, spotlights and a cursor aimed at captured element boxes.", "Cross-dissolves between screens with depth", "104 BPM clean groove: soft kick, hats, Dm9-Bbmaj7-Fmaj7-C6 plucks", "Screen whooshes, extraction blips, gate chimes, cursor click, receipt printer"),
 "pipeline": ("E1 · Job pipeline", "Three.js pipeline: Arbeitnow and 16 Greenhouse boards emit raw postings (Adzuna, The Muse, Lever shown dim as 'when configured'); a gate turns raw shapes into six-field records; a fingerprint ring merges duplicates; a store drops stale listings; a 24 h ring and the real 'Live job data is unavailable' notice.", "Camera dollies station to station along the pipeline.", "Push into depth", "Precision 16th arpeggios, lighter kick, darker harmony", "Data blips throughout, field ticks, hash chime, stale-drop thunks, clock ticks"),
 "engine": ("E2 · Match engine", "SVG dial where each arc's WIDTH is its published weight and its DEPTH the factor score; real FACTOR_WEIGHTS code highlights as each is named; README worked example sums to 86, then eligibility and sponsorship block, the sum drops to 64 and the cap takes it to 35; ranking ladder swaps.", "Dial scales left for the ladder.", "Cross-dissolve", "Continues; drums drop for the cap", "Factor ticks, count-up blips, drain whoosh, impact on 'capped'"),
 "arch": ("F · Engineering", "CSS 3D exploded stack: Experience (Next.js 16) / Server / Domain services / Repository interface / Data. Supabase slab slides out for the in-memory store. Close-ups: two candidates' rows with an RLS wall a probe cannot cross (PGlite policy tests); AIProvider routing Claude → Zod schema, switching to the rules provider; a queue with idempotency keys, two workers, a failing job backing off to dead-letter.", "Slow orbit of the isometric stack, then three framed close-ups.", "Depth dissolves", "Same technical bed", "Layer thunks, tile ticks, swap whoosh, block impact, pass chime, glitch, switch click, retry blips"),
 "results": ("G · Live today", "Screens captured from www.skylarkgo.in (landing, sign-in with Google, rupee pricing) and the demo review queue, with five verified live capabilities; then two roadmap items from the README on a dashed horizon.", "Screen swaps synced to each capability.", "Cross-dissolve", "Brighter build: F-C-Dm-Bb, full groove", "Item ticks, transition whoosh"),
 "close": ("H · Close", "Typographic thesis, then three serif lines, then the official logo reassembles with the tagline 'Your next move, already in motion.', the URL, GitHub repo and team credit.", "Static, centred; restraint.", "Fade to black", "Drums out, pads and bells, resolves to F(add9) on the logo", "Reverse whoosh, riser, shard thunks, final impact"),
}
sb = ["# Skylark film · shot-by-shot storyboard", "", f"Runtime {mmss(tl['total'])} at 30 fps. Times come from `src/data/timeline.json`, the single clock that drives the visuals, the subtitles and every sound cue. Regenerate with `python3 production/tools/make_docs.py`.", ""]
for name, sc in tl["scenes"].items():
    title, visual, camera, trans, music, sfx = SCENES[name]
    sb += [f"## {title} · {mmss(sc['start'])} – {mmss(sc['end'])}", "", f"**Visual.** {visual}", "", f"**Camera.** {camera}  ", f"**Transition in.** {trans}  ", f"**Music.** {music}  ", f"**Sound effects.** {sfx}", "", "| Line | Start | End | Narration |", "|---:|---:|---:|---|"]
    for l in tl["lines"]:
        if l["scene"] == name: sb.append(f"| {l['id']} | {mmss(l['start'])} | {mmss(l['end'])} | {l['text']} |")
    sb.append("")
open(ROOT / "production/storyboard.md", "w").write("\n".join(sb))
sc = ["# Skylark film · narration script", "", "Final script as narrated. Pronunciation respellings sent to the voice engine are in `script.json` (`tts`).", ""]
for name in tl["scenes"]:
    sc += [f"## {SCENES[name][0]}", ""] + [l["text"] for l in tl["lines"] if l["scene"] == name] + [""]
open(ROOT / "production/script.md", "w").write("\n\n".join(x for x in sc if x) + "\n")
print("ok")
